#include <bits/stdc++.h>
using namespace std;
const int INF = 1e9 + 5;

int main(){
    int T; cin >> T;
    while(T--){
        int N, M; cin >> N >> M;
        vector<int> a(N), b(M);
        for(int i = 0; i < N; i++) cin >> a[i];
        for(int i = 0; i < M; i++) cin >> b[i];
        vector<int> backwards_match(M);
        int j = N - 1;
        for(int i = M - 1; i >= 0; i--){
            while(j >= 0 && a[j] < b[i]) j--;
            backwards_match[i] = j--;
        }
        vector<int> forwards_match(M);
        j = 0;
        for(int i = 0; i < M; i++){
            while(j < N && a[j] < b[i]) j++;
            forwards_match[i] = j++;
        }
        if(forwards_match.back() < N){
            cout << 0 << endl;
            continue;
        }
        int ans = INF;
        for(int i = 0; i < M; i++){
            int match_previous = i == 0 ? -1 : forwards_match[i - 1];
            int match_next = i + 1 == M ? N : backwards_match[i + 1];
            if(match_next > match_previous){
                ans = min(ans, b[i]);
            }
        }
        cout << (ans == INF ? -1 : ans) << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
#define int long long

void solve() {
    int n, q; cin >> n >> q;
    int arr[n+1];
    vector<int> idx(n+1, 0);
    for (int i = 1; i <= n; i++) {
        cin >> arr[i];
        idx[arr[i]] = i;
    }
    while (q--) {
        int l, r, k; cin >> l >> r >> k;
        if (idx[k] > r || idx[k] < l) {
            cout << -1 << " ";
            continue;
        }
        int big = n - k, small = k - 1;
        int needBig = 0, needSmall = 0;
        int bigAv = n - k, smallAv = k - 1;
        int lo = l, hi = r;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (arr[mid] == k) break;
            if (mid < idx[k]) { // i want to go right
                if (k < arr[mid]) {
                    needSmall++;
                }
                else smallAv--;
                small--;
                lo = mid+1;
            }
            else { // i want to go left
                if (k > arr[mid]) { 
                    needBig++;
                }
                else bigAv--;
                big--;
                hi = mid-1;
            }
        }
        if (big < 0 || small < 0) {
            cout << -1 << " ";
            continue;
        }
        int ans = 2 * min(needBig, needSmall);
        int diff = abs(needBig - needSmall);
        if (needBig > needSmall) {
            if (bigAv < diff) cout << -1 << " ";
            else cout << ans + 2 * diff << " ";
        }
        else {
            if (smallAv < diff) cout << -1 << " ";
            else cout << ans + 2 * diff << " ";
        }
    }
}

