mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
int uid(int a, int b) { return uniform_int_distribution<int>(a, b)(rng); }
ll uld(ll a, ll b) { return uniform_int_distribution<ll>(a, b)(rng); }

struct DSU{
    vector<int> p, sz;
    vector<ll> score;

    DSU(int n){
        p.assign(n, 0);
        sz.assign(n, 1);
        score.assign(n, 0);

        for (int i = 0; i < n; i++) p[i] = i;
    }

    int find(int u){
        if (p[u] == u) return u;
        p[u] = find(p[u]);
        return p[u];
    }

    void unite(int u, int v){
        u = find(u);
        v = find(v);
        if (u == v) return;

        if (sz[u] < sz[v]) swap(u, v);
        p[v] = u;
        sz[u] += sz[v];
        score[u] += score[v];
    }

    bool same(int u, int v){
        return find(u) == find(v);
    }

    int size(int u){
        u = find(u);
        return sz[u];
    }
};

void solve(){
    int n;
    cin >> n;

    string s;
    cin >> s;

    DSU dsu(2 * n);
    vector<array<int, 2>> prev;
    for (int i = 0; i < n; i++){
        if (s[i] == '1'){
            dsu.score[2 * i] = 1;
            dsu.unite(2 * i, 2 * i + 1);

            for (int j = 0; j < prev.size(); j++){
                int l = prev[j][0];
                int r = prev[j][1];
                if (i >= l && i <= r)
                    dsu.unite(2 * i, 2 * (i - 1) + j);
            }
            prev = {{i, i}};
            continue;
        }

        vector<array<int, 2>> nxt = {{0, i - 1}, {i + 1, n - 1}};
        for (int j = 0; j < nxt.size(); j++){
            auto [l, r] = nxt[j];
            dsu.score[2 * i + j] = r - l + 1;
        }

        for (int j = 0; j < prev.size(); j++){
            for (int k = 0; k < nxt.size(); k++){
                auto [l1, r1] = prev[j];
                auto [l2, r2] = nxt[k];

                if (l2 > r1 || r2 < l1)
                    continue;

                dsu.unite(2 * i + k, 2 * (i - 1) + j);
            }
        }
        prev = nxt;
    }

    ll ans = 0;
    for (int i = 0; i < 2 * n; i++)
        ans = max(ans, dsu.score[i]);
    cout << ans << "\n";
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int t;
    cin >> t;
    while (t--) solve();
}

